import React, { useEffect, useState } from "react";
import ChatSidebar from "../components/ChatSidebar";
import ChatMain from "../components/ChatMain";
import axios from "axios";
import "../styles/Chat.css";

const Chat = () => {
  const [selectedConversation, setSelectedConversation] = useState(null);
  const [messages, setMessages] = useState([]);
  const [newMessage, setNewMessage] = useState("");
  const [user, setUser] = useState(null);

  // ✅ Load user from localStorage
  useEffect(() => {
    const storedUser = JSON.parse(localStorage.getItem("user"));
    setUser(storedUser);
  }, []);

  // ✅ Debug log for state
  useEffect(() => {
    console.log("👤 Loaded user:", user);
    console.log("💬 Selected conversation:", selectedConversation);
  }, [user, selectedConversation]);

  // ✅ Fetch messages
  useEffect(() => {
    const fetchMessages = async () => {
      if (!selectedConversation?._id || !user?._id) return;

      try {
        const res = await axios.get(`/api/messages/${selectedConversation._id}`);
        const formatted = res.data.map((msg) => ({
          ...msg,
          fromSelf: msg.senderId === user._id,
        }));
        setMessages(formatted);
      } catch (error) {
        console.error("❌ Error fetching messages:", error);
      }
    };

    fetchMessages();
  }, [selectedConversation, user]);

  // ✅ Send a message
  const handleSend = async () => {
    console.log("🟠 Send button clicked");

    const conversationId = selectedConversation._id || selectedConversation.id;

if (!newMessage.trim() || !conversationId || !user?._id) {
  console.warn("⚠️ Cannot send message: Missing data", {
    newMessage,
    selectedConversation,
    user,
  });
  return;
}


const payload = {
  conversationId,
  senderId: user._id,
  senderUsername: user.username,
  text: newMessage,
};


    console.log("📤 Sending:", payload);

    try {
      const res = await axios.post("/api/messages", payload);
      setMessages((prev) => [...prev, { ...res.data, fromSelf: true }]);
      setNewMessage("");
    } catch (error) {
      console.error("❌ Error sending message:", error);
    }
  };

  return (
    <div className="chat-container">
      <ChatSidebar
        onSelectConversation={setSelectedConversation}
        selectedConversation={selectedConversation}
      />
      <ChatMain
        selectedConversation={selectedConversation}
        messages={messages}
        newMessage={newMessage}
        setNewMessage={setNewMessage}
        handleSend={handleSend}
        user={user}
      />
    </div>
  );
};

export default Chat;
